<?php
declare(strict_types=1);
use GlpiPlugin\Demandas\AccessPolicy;use GlpiPlugin\Demandas\Profile as DemandasProfile;
Session::checkLoginUser();AccessPolicy::check(DemandasProfile::VIEW_TIME_PORTAL);$canHoliday=AccessPolicy::has(DemandasProfile::MANAGE_HOLIDAYS);$canAccess=AccessPolicy::has(DemandasProfile::MANAGE_TIME_ACCESS);if(!$canHoliday&&!$canAccess&&!AccessPolicy::has(DemandasProfile::VIEW_TEAM_ATTENDANCE))throw new Glpi\Exception\Http\AccessDeniedHttpException();$db=DBConnection::getReadConnection();
if($_SERVER['REQUEST_METHOD']==='POST'){try{if(isset($_POST['save_holiday'])){AccessPolicy::check(DemandasProfile::MANAGE_HOLIDAYS);$db->insert('glpi_plugin_demandas_holidays',['name'=>mb_substr(trim((string)$_POST['name']),0,255),'holiday_date'=>$_POST['holiday_date'],'scope'=>$_POST['scope'],'state_code'=>mb_strtoupper(trim((string)($_POST['state_code']??''))),'municipality'=>mb_substr(trim((string)($_POST['municipality']??'')),0,120),'is_working_day'=>isset($_POST['is_working_day'])?1:0,'substitute_date'=>trim((string)($_POST['substitute_date']??''))?:null,'notes'=>mb_substr(trim((string)($_POST['notes']??'')),0,2000),'created_by'=>(int)Session::getLoginUserID(),'date_creation'=>date('Y-m-d H:i:s')]);}elseif(isset($_POST['save_access'])){AccessPolicy::check(DemandasProfile::MANAGE_TIME_ACCESS);$u=(int)$_POST['users_id'];$right=(string)$_POST['right_name'];if(!array_key_exists($right,DemandasProfile::definitions()))throw new RuntimeException('Permissão inválida.');$found=[];foreach($db->request(['FROM'=>'glpi_plugin_demandas_user_rights','WHERE'=>['users_id'=>$u,'right_name'=>$right],'LIMIT'=>1])as$r)$found=$r;$data=['users_id'=>$u,'right_name'=>$right,'decision'=>(int)$_POST['decision'],'date_mod'=>date('Y-m-d H:i:s')];if($found)$db->update('glpi_plugin_demandas_user_rights',$data,['id'=>(int)$found['id']]);else$db->insert('glpi_plugin_demandas_user_rights',$data);}Session::addMessageAfterRedirect('Configuração salva.',true,INFO);}catch(Throwable$e){Session::addMessageAfterRedirect($e->getMessage(),true,ERROR);}Html::redirect('/plugins/demandas/front/timeclock-admin.php');}
function ta(string$v):string{return htmlspecialchars($v,ENT_QUOTES);}Html::header('Administração do Ponto',$_SERVER['PHP_SELF'],'management',GlpiPlugin\Demandas\WorkforceHub::class);echo"<div class='container-xl'><h1>Administração do ponto</h1><div class='row g-4'>";
if($canHoliday){echo"<div class='col-lg-6'><div class='card'><div class='card-header'><h2 class='card-title'>Feriados e compensações</h2></div><div class='card-body'><form method='post'><input type='hidden' name='_glpi_csrf_token' value='".Session::getNewCSRFToken()."'><div class='row g-3'><div class='col-8'><label class='form-label'>Nome</label><input class='form-control' name='name' required></div><div class='col-4'><label class='form-label'>Data</label><input class='form-control' type='date' name='holiday_date' required></div><div class='col-4'><label class='form-label'>Abrangência</label><select class='form-select' name='scope'><option value='international'>Internacional</option><option value='national' selected>Nacional</option><option value='state'>Estadual</option><option value='municipal'>Municipal</option></select></div><div class='col-2'><label class='form-label'>UF</label><input class='form-control' name='state_code' maxlength='2'></div><div class='col-6'><label class='form-label'>Município</label><input class='form-control' name='municipality'></div><div class='col-6'><label class='form-label'>Dia de compensação</label><input class='form-control' type='date' name='substitute_date'></div><div class='col-6 d-flex align-items-end'><label class='form-check'><input class='form-check-input' type='checkbox' name='is_working_day'><span class='form-check-label'>Empresa trabalhará neste feriado</span></label></div><div class='col-12'><textarea class='form-control' name='notes' placeholder='Observações'></textarea></div></div><button class='btn btn-primary mt-3' name='save_holiday'>Adicionar feriado</button></form></div><div class='table-responsive'><table class='table'><thead><tr><th>Data</th><th>Feriado</th><th>Abrangência</th><th>Compensação</th></tr></thead><tbody>";foreach($db->request(['FROM'=>'glpi_plugin_demandas_holidays','ORDER'=>['holiday_date DESC'],'LIMIT'=>100])as$h)echo"<tr><td>".ta(date('d/m/Y',strtotime($h['holiday_date'])))."</td><td>".ta($h['name'])."</td><td>".ta($h['scope'])."</td><td>".ta($h['substitute_date']?date('d/m/Y',strtotime($h['substitute_date'])):'—')."</td></tr>";echo"</tbody></table></div></div></div>";}
if($canAccess){$rights=[DemandasProfile::VIEW_TIME_PORTAL,DemandasProfile::LOG_OWN_TIME,DemandasProfile::LOG_OTHERS_TIME,DemandasProfile::VIEW_OWN_ATTENDANCE,DemandasProfile::VIEW_TEAM_ATTENDANCE,DemandasProfile::MANAGE_ATTENDANCE,DemandasProfile::MANAGE_HOLIDAYS];echo"<div class='col-lg-6'><div class='card'><div class='card-header'><h2 class='card-title'>Exceções individuais</h2></div><div class='card-body'><p class='text-muted'>A decisão individual prevalece sobre o perfil. Use “herdar” removendo a exceção em uma revisão administrativa futura.</p><form method='post'><input type='hidden' name='_glpi_csrf_token' value='".Session::getNewCSRFToken()."'><label class='form-label'>Usuário</label><select class='form-select mb-3' name='users_id'>";foreach($db->request(['SELECT'=>['id','name','realname','firstname'],'FROM'=>'glpi_users','WHERE'=>['is_active'=>1],'ORDER'=>['realname ASC']])as$u)echo"<option value='".(int)$u['id']."'>".ta(trim($u['firstname'].' '.$u['realname'])?:$u['name'])."</option>";echo"</select><label class='form-label'>Permissão</label><select class='form-select mb-3' name='right_name'>";foreach($rights as$r)echo"<option value='".ta($r)."'>".ta(DemandasProfile::definitions()[$r])."</option>";echo"</select><label class='form-label'>Decisão individual</label><select class='form-select mb-3' name='decision'><option value='1'>Permitir</option><option value='0'>Negar</option></select><button class='btn btn-primary' name='save_access'>Salvar exceção</button></form></div></div></div>";}echo"</div></div>";Html::footer();
